:root{
  --bg:#0b0e13; --bg2:#11161e; --bg3:#161c26; --line:#232b38; --line2:#2e3849;
  --ink:#e8edf5; --dim:#8b97a8; --dim2:#5f6b7d;
  --amber:#f0b429; --amber2:#ffd166; --teal:#2dd4a7; --brick:#e2635c; --slate:#7c8cff;
  --mono:ui-monospace,SFMono-Regular,"SF Mono",Menlo,Consolas,monospace;
  --sans:system-ui,-apple-system,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;
}
*{box-sizing:border-box}
html,body{margin:0;background:var(--bg);color:var(--ink);font-family:var(--sans);font-size:13px;line-height:1.45}
