.brand-sub{color:var(--dim2)}
h1{font-size:19px;letter-spacing:-.01em;margin:8px 0 4px}
.subline{color:var(--dim);font-size:12px}
.subline b{color:var(--amber2);font-variant-numeric:tabular-nums}
