.stamp{display:flex;gap:8px;align-items:baseline}
.stamp-k{color:var(--dim2);letter-spacing:.12em;font-size:9px}
.stamp-v{color:var(--ink)}
.legend{display:flex;gap:5px}
.kpis{display:grid;grid-template-columns:repeat(6,1fr);gap:1px;background:var(--line);border:1px solid var(--line);margin:14px 0}
.kpi{background:var(--bg2);padding:11px 13px}
.kpi-v{font-size:20px;font-weight:650;font-variant-numeric:tabular-nums;letter-spacing:-.02em}
