.mini-h{font-size:9px;letter-spacing:.13em;color:var(--dim);margin:8px 0 4px}
.hint{letter-spacing:0;text-transform:none;color:var(--dim2);font-size:10px}
.dim-h{color:var(--dim2)}
.terms td,.terms th{padding:3px 6px 3px 0;font-size:11px;border-bottom:1px solid #1b2230;text-align:left}
