.result-count{font-family:var(--mono);font-size:11px;color:var(--dim);margin-left:auto;align-self:center}
.btn{background:var(--bg3);border:1px solid var(--line2);color:var(--ink);font-size:10px;letter-spacing:.1em;padding:6px 9px;cursor:pointer}
