.tabs{display:flex;gap:2px;border-bottom:1px solid var(--line)}
.tab{background:none;border:0;border-bottom:2px solid transparent;color:var(--dim);font-size:11px;letter-spacing:.08em;padding:8px 13px;cursor:pointer}
