.board-wrap{overflow:auto;max-height:none}
.board{font-size:12px}
.board thead th{position:sticky;top:0;background:var(--bg);z-index:2;text-align:left;font-size:9px;letter-spacing:.1em;color:var(--dim2);font-weight:500;padding:7px 7px;border-bottom:1px solid var(--line2);white-space:nowrap;cursor:pointer;user-select:none}
.board thead th.num{text-align:right}
