.board tbody tr.sel{background:#1a2130;box-shadow:inset 2px 0 0 var(--amber)}
.board td{padding:5px 7px;vertical-align:middle}
.rk{font-family:var(--mono);color:var(--dim2);font-size:11px;width:34px}
.pname{font-weight:600}
.pslug{font-family:var(--mono);font-size:10px;color:var(--dim2)}
