.dr-x{background:none;border:1px solid var(--line2);color:var(--dim);cursor:pointer;font-size:11px;padding:3px 7px}
.dr-sec{margin-top:13px}
.dr-sec h4{margin:0 0 6px;font-size:9px;letter-spacing:.13em;color:var(--dim2);font-weight:600;text-transform:uppercase}
.kv{display:grid;grid-template-columns:1fr auto;gap:3px 10px;font-size:11px}
.kv dt{color:var(--dim)}
.kv dd{margin:0;font-family:var(--mono);font-variant-numeric:tabular-nums;text-align:right}
.dr-range{display:flex;align-items:center;gap:8px;font-family:var(--mono);font-size:11px;color:var(--dim)}
.dr-range .track{flex:1;height:7px;background:#1c2430;position:relative}
.dr-range .fill{position:absolute;top:0;bottom:0;background:var(--amber);opacity:.5}
.dr-range .mid{position:absolute;top:-3px;bottom:-3px;width:2px;background:var(--amber2)}
.ledger{margin:0;padding-left:0;list-style:none;counter-reset:st}
.ledger li{counter-increment:st;position:relative;padding:5px 0 5px 26px;border-bottom:1px solid #1a2029;font-size:11.5px;color:#c6cfdb}
.ledger li:before{content:counter(st,decimal-leading-zero);position:absolute;left:0;top:5px;font-family:var(--mono);font-size:9px;color:var(--amber)}
.econ{background:var(--bg3);border:1px solid var(--line);padding:8px 10px;font-family:var(--mono);font-size:11px;color:#c6cfdb}
.econ b{color:var(--amber2)}
.foot{display:flex;justify-content:space-between;gap:20px;border-top:1px solid var(--line);margin-top:16px;padding-top:7px;font-size:10px;color:var(--dim2);font-family:var(--mono)}
@media (max-width:1100px){.proof{grid-template-columns:1fr}.kpis{grid-template-columns:repeat(3,1fr)}.two-col{grid-template-columns:1fr}}
@media (prefers-reduced-motion:reduce){*{transition:none!important}}
